"use client";

import { motion } from "framer-motion";
import { ChevronLeft, ChevronRight } from "lucide-react";

interface PaginationProps {
  currentPage: number;
  totalPages: number;
  onPageChange: (page: number) => void;
  className?: string;
}

export default function Pagination({
  currentPage,
  totalPages,
  onPageChange,
  className = "",
}: PaginationProps) {
  if (totalPages <= 1) return null;

  const getPageNumbers = () => {
    const pages = [];
    const maxVisible = 5;
    let start = Math.max(1, currentPage - Math.floor(maxVisible / 2));
    let end = Math.min(totalPages, start + maxVisible - 1);

    if (end - start + 1 < maxVisible) {
      start = Math.max(1, end - maxVisible + 1);
    }

    for (let i = start; i <= end; i++) {
      pages.push(i);
    }

    return pages;
  };

  const pageNumbers = getPageNumbers();

  return (
    <div className={`flex items-center justify-center gap-1.5 ${className}`}>
      <button
        onClick={() => onPageChange(currentPage - 1)}
        disabled={currentPage === 1}
        className={`p-2 rounded-lg transition-all duration-200 ${
          currentPage === 1
            ? "text-[#4f6459] cursor-not-allowed"
            : "text-[#6f8a7d] hover:text-[#c6d2ca] hover:bg-[rgba(34,229,122,.06)]"
        }`}
        aria-label="Previous page"
      >
        <ChevronLeft size={18} />
      </button>

      {pageNumbers[0] > 1 && (
        <>
          <button
            onClick={() => onPageChange(1)}
            className="min-w-[36px] h-9 rounded-lg text-sm font-mono text-[#6f8a7d] hover:text-[#c6d2ca] hover:bg-[rgba(34,229,122,.06)] transition-all duration-200"
          >
            1
          </button>
          {pageNumbers[0] > 2 && (
            <span className="text-[#4f6459] text-sm font-mono px-1">…</span>
          )}
        </>
      )}

      {pageNumbers.map((page) => (
        <motion.button
          key={page}
          onClick={() => onPageChange(page)}
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
          className={`min-w-[36px] h-9 rounded-lg text-sm font-mono font-medium transition-all duration-200 ${
            page === currentPage
              ? "bg-[#22e57a] text-[#05100a] shadow-[0_0_20px_rgba(34,229,122,.2)]"
              : "text-[#6f8a7d] hover:text-[#c6d2ca] hover:bg-[rgba(34,229,122,.06)]"
          }`}
        >
          {page}
        </motion.button>
      ))}

      {pageNumbers[pageNumbers.length - 1] < totalPages && (
        <>
          {pageNumbers[pageNumbers.length - 1] < totalPages - 1 && (
            <span className="text-[#4f6459] text-sm font-mono px-1">…</span>
          )}
          <button
            onClick={() => onPageChange(totalPages)}
            className="min-w-[36px] h-9 rounded-lg text-sm font-mono text-[#6f8a7d] hover:text-[#c6d2ca] hover:bg-[rgba(34,229,122,.06)] transition-all duration-200"
          >
            {totalPages}
          </button>
        </>
      )}

      <button
        onClick={() => onPageChange(currentPage + 1)}
        disabled={currentPage === totalPages}
        className={`p-2 rounded-lg transition-all duration-200 ${
          currentPage === totalPages
            ? "text-[#4f6459] cursor-not-allowed"
            : "text-[#6f8a7d] hover:text-[#c6d2ca] hover:bg-[rgba(34,229,122,.06)]"
        }`}
        aria-label="Next page"
      >
        <ChevronRight size={18} />
      </button>
    </div>
  );
}
